import{c as i,ah as o,L as d,O as l}from"./chunks/framework.YKVbmyBD.js";const b=JSON.parse('{"title":"认识 Linux 系统","description":"","frontmatter":{},"headers":[],"relativePath":"web-src/fovlin-notes/linux-guide/os-guide.md","filePath":"web-src/fovlin-notes/linux-guide/os-guide.md"}'),a={name:"web-src/fovlin-notes/linux-guide/os-guide.md"};function s(c,e,p,t,n,h){return o(),d("div",null,[...e[0]||(e[0]=[l('<h1 id="认识-linux-系统" tabindex="-1">认识 Linux 系统 <a class="header-anchor" href="#认识-linux-系统" aria-label="Permalink to “认识 Linux 系统”">​</a></h1><h2 id="系统文件目录结构" tabindex="-1">系统文件目录结构 <a class="header-anchor" href="#系统文件目录结构" aria-label="Permalink to “系统文件目录结构”">​</a></h2><p>一个 Linux 系统的文件系统由一个根目录 <code>/</code> 以及此目录下的所有文件与目录构成，根目录下的文件与目录有着如下结构：</p><ul><li><p><code>/</code>：根文件系统，所有挂载点与路径的起点。包含系统必须的子目录与入口结构。</p><ul><li><p><code>bin</code>：系统启动和单用户模式下必须的基础命令，所有用户可执行。</p></li><li><p><code>boot</code>：启动所需文件：内核、initramfs、引导配置。</p></li><li><p><code>dev</code>：设备节点集合，一切皆文件。</p></li><li><p><code>etc</code>：系统级配置中心，统一存放所有服务和系统配置。</p></li><li><p><code>home</code>：普通用户的个人主目录集合。</p></li><li><p><code>lib</code>：与 <code>lib64</code> 共同构成系统启动核心库、动态链接器所在位置。</p></li><li><p><code>lib64</code>：与 <code>lib</code> 共同构成系统启动核心库、动态链接器所在位置。</p></li><li><p><code>mount</code>：</p></li><li><p><code>opt</code>：</p></li><li><p><code>proc</code>：由内核提供的虚拟文件系统，展示系统与进程的实时信息。</p></li><li><p><code>root</code>：<code>root</code> 用户的家目录</p></li><li><p><code>run</code>：运行时数据存放点，重启后清空。</p></li><li><p><code>sbin</code>：系统管理与维护命令，面向 root。</p></li><li><p><code>srv</code>：</p></li><li><p><code>sys</code>：</p></li><li><p><code>tmp</code>：</p></li><li><p><code>usr</code>：用户级程序与库的主集合，包含大部分系统软件、文档与工具。</p></li><li><p><code>var</code>：频繁变化的数据：日志、缓存、数据库运行文件等。</p></li></ul></li></ul><h2 id="路径" tabindex="-1">路径 <a class="header-anchor" href="#路径" aria-label="Permalink to “路径”">​</a></h2><p>路径表示文件或目录所在的位置，表示方式有两种，一种为绝对路径，一种为相对路径。</p><p>绝对路径为从根目录出发，指向文件所在位置，例如 <code>/home/fovlin/file</code>。</p><p>相对路径表示从当前目录出发，指向文件所在位置，<code>./</code>表示当前工作目录，<code>../</code> 表示上级目录，<code>~/</code>表示用户家目录，运行当前目录下的可执行文件。</p><p>其中 <code>./</code> 在不作为命令时可忽略，<code>file</code> 也表示当前目录下名为 <code>file</code> 的文件，但在命令行首项并不能省略，否则会和 <code>$PATH</code> 变量的调用冲突，若在首项忽略 <code>./</code> 会被当作命令处理。</p><h2 id="环境变量" tabindex="-1">环境变量 <a class="header-anchor" href="#环境变量" aria-label="Permalink to “环境变量”">​</a></h2><p>环境变量（Environment Variables）是操作系统中存储的一组动态命名的值，由变量名和变量值组成，相当于系统的“信息库”。程序运行时可以读取这些变量，从而获取配置信息或调整运行行为。</p><p>变量在 Linux 中使用 <code>$</code> + <code>变量名</code> 进行表示。</p><p>上文中 <code>$PATH</code> 变量就是一个很好的例子。</p><p>要查看当前生效的所有环境变量，使用 <code>env</code> 命令：</p><div class="language-bash"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">env</span></span></code></pre></div><p>同时可以使用 <code>export</code> 命令自定义环境变量，这种效果是临时的，在会话结束即失效。</p><p>设置一个环境变量，使用如下格式：</p><div class="language-txt"><button title="Copy Code" class="copy"></button><span class="lang">txt</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>export &lt;变量名&gt;=&lt;值&gt;</span></span></code></pre></div><p>如将 <code>/opt/java/bin</code> 目录临时添加到 <code>$PATH</code> 变量中，即设置 <code>$PATH</code> 的值为 <code>$PATH:/opt/java/bin</code> 使用如下命令：</p><div class="language-bash"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">export</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> $PATH=$PATH:/opt/java/bin</span></span></code></pre></div><p>此命令的的意思为，在 <code>$PATH</code> 变量原有的结构上，再添加 <code>:/opt/java/bin</code> 字段，并将 $PATH 变量重新设置为后续值，若你不熟悉此变量的结构，可以参考上文的 <code>$PATH</code> 变量说明</p><p>要想使环境变量永久生效，应该将上述 <code>export</code> 命令写入 Shell 的环境变量文件。</p><blockquote><p>此处的 Shell 以 bash 为例。</p></blockquote><p>Shell 在启动时会读取一遍环境变量文件，其本质是将环境变量文件当作 Shell 脚本在 Shell 启动时运行一次，这类文件有 <code>/etc/profile</code> <code>~/.bashrc</code> <code>~/.bash_profile</code>，其中后两者位于用户家目录下的环境变量文件仅对当前用户生效。</p><p>编辑文件，在新行写入你要应用的环境变量即可，上文举例更改 <code>$PATH</code> 变量，要使其永久生效，写入以下行：</p><div class="language-bash"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">export</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> $PATH=$PATH:/opt/java/bin</span></span></code></pre></div><blockquote><p>编辑文件的方式将会在后续提及。</p></blockquote>',27)])])}const k=i(a,[["render",s]]);export{b as __pageData,k as default};
